#!/usr/bin/env bash
set -euo pipefail
WORKSPACE="/home/kavia/workspace/code-generation/tic-tac-toe-classic-324324/database"
cd "$WORKSPACE"
[ -f package.json ] && exit 0
cat > package.json <<'JSON'
{
  "name": "db-static-frontend",
  "version": "0.0.1",
  "private": true,
  "scripts": {
    "start": "node server.js",
    "build": "mkdir -p dist && cp -r public/* dist/",
    "test": "jest --passWithNoTests"
  },
  "devDependencies": {
    "jest": "29.x"
  }
}
JSON
mkdir -p public
cat > public/index.html <<'HTML'
<!doctype html><html><head><meta charset="utf-8"><title>DB Frontend</title></head><body><div id="app">OK</div><script src="app.js"></script></body></html>
HTML
cat > public/app.js <<'JS'
console.log('db frontend running');
JS
# server serves dist/; PORT default unified to 3000
cat > server.js <<'NODE'
const http = require('http'), fs = require('fs'), path = require('path');
const port = process.env.PORT || 3000;
const base = path.join(__dirname,'dist');
function send(res, p){fs.readFile(path.join(base,p),(e,d)=>{if(e){res.writeHead(404);res.end();}else{res.writeHead(200);res.end(d);}})}
const srv = http.createServer((req,res)=>{const p = req.url === '/' ? '/index.html' : req.url; send(res,p);});
if(require.main === module){srv.listen(port,()=>console.log('listening',port));}
module.exports = srv;
NODE
exit 0

